   941	func runSemanticGC(ctx context.Context, cmd *cobra.Command, opts Options, target, olderThan string) error {
   942		cutoff, err := parseAgeCutoff(olderThan, opts.Now().UTC())
   943		if err != nil {
   944			return err
   945		}
   946		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
   947		if err != nil {
   948			return err
   949		}
   950		if !local {
   951			return fmt.Errorf("gc requires a local repository path: %s", target)
   952		}
   953		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
   954		if err != nil {
   955			return err
   956		}
   957		unlock, err := acquireSemanticIndexLock(storage.BrainDir)
   958		if err != nil {
   959			return err
   960		}
   961		defer unlock()
   962		manifest, err := loadBrainManifest(storage.BrainDir)
   963		if err != nil {
   964			return err
   965		}
   966		active := ""
   967		if manifest != nil && manifest.Sources != nil && manifest.Sources.Semantic != nil {
   968			active = filepath.Clean(filepath.Join(storage.BrainDir, filepath.FromSlash(manifest.Sources.Semantic.SnapshotPath), ".."))
   969		}
   970		snapshotsRoot := filepath.Join(storage.BrainDir, semanticDirName, semanticSnapshotsDir)
   971		entries, err := os.ReadDir(snapshotsRoot)
   972		if err != nil {
   973			if os.IsNotExist(err) {
   974				fmt.Fprintln(cmd.OutOrStdout(), "pruned semantic snapshots: 0")
   975				return nil
   976			}
   977			return err
   978		}
   979		pruned := 0
   980		for _, entry := range entries {
   981			if !entry.IsDir() {
   982				continue
   983			}
   984			path := filepath.Join(snapshotsRoot, entry.Name())
   985			if active != "" && filepath.Clean(path) == active {
   986				continue
   987			}
   988			info, err := entry.Info()
   989			if err != nil {
   990				continue
   991			}
   992			if info.ModTime().Before(cutoff) {
   993				if err := os.RemoveAll(path); err != nil {
   994					return err
   995				}
   996				pruned++
   997			}
   998		}
   999		fmt.Fprintf(cmd.OutOrStdout(), "pruned semantic snapshots: %d\n", pruned)
  1000		return nil
  1001	}
