  1488	func readSemanticSnapshotSummary(path, repoKey string) (semanticHeader, semanticCounts, error) {
  1489		f, err := os.Open(path)
  1490		if err != nil {
  1491			return semanticHeader{}, semanticCounts{}, err
  1492		}
  1493		defer f.Close()
  1494		scanner := newSemanticScanner(f)
  1495		if !scanner.Scan() {
  1496			if err := scanner.Err(); err != nil {
  1497				return semanticHeader{}, semanticCounts{}, err
  1498			}
  1499			return semanticHeader{}, semanticCounts{}, errors.New("semantic snapshot missing header")
  1500		}
  1501		var header semanticHeader
  1502		if err := json.Unmarshal(scanner.Bytes(), &header); err != nil {
  1503			return semanticHeader{}, semanticCounts{}, fmt.Errorf("parse semantic snapshot header: %w", err)
  1504		}
  1505		if header.RepoKey == "" {
  1506			return semanticHeader{}, semanticCounts{}, errors.New("semantic snapshot header missing repo_key")
  1507		}
  1508		if header.RepoKey != repoKey {
  1509			return semanticHeader{}, semanticCounts{}, fmt.Errorf("semantic snapshot repo_key %q does not match current repo %q", header.RepoKey, repoKey)
  1510		}
  1511		if err := validateSemanticSchema(header.SchemaVersion); err != nil {
  1512			return semanticHeader{}, semanticCounts{}, fmt.Errorf("semantic snapshot schema unsupported: %w", err)
  1513		}
  1514		line := 1
  1515		var counts semanticCounts
  1516		for scanner.Scan() {
  1517			line++
  1518			text := bytes.TrimSpace(scanner.Bytes())
  1519			if len(text) == 0 {
  1520				continue
  1521			}
  1522			var record semanticRecord
  1523			if err := json.Unmarshal(text, &record); err != nil {
  1524				return semanticHeader{}, semanticCounts{}, fmt.Errorf("parse semantic snapshot line %d: %w", line, err)
  1525			}
  1526			switch record.RecordType {
  1527			case "symbol":
  1528				counts.Symbols++
  1529			case "relation":
  1530				counts.Relations++
  1531			}
  1532		}
  1533		if err := scanner.Err(); err != nil {
  1534			return semanticHeader{}, semanticCounts{}, err
  1535		}
  1536		return header, counts, nil
  1537	}
